{#- Code generated by authfly/codegen from specs/widgets/sign-in.def.ts. DO NOT EDIT.
    Authfly sign-in on UI8Kit 3 primitives. Axes: method (password | magic), identifier (any | email | username),
    social (none | show: provider buttons, an extension point). Props identical to the xgen widget. -#}
{%- import 'authfly/components.html.j2' as af -%}
{%- set id = p.id or '' -%}{%- set l = p.labels or {} -%}{%- set error = p.error or '' -%}
{%- set formError = id ~ '-error' if error else none -%}
{%- set c5 -%}
{{ af.head(id, p.title or '', p.text or '') }}
{{ af.messages(id, error, '') }}
{%- if (p.social or 'none') == 'show' -%}
{%- set c2 -%}{%- for pr in p.providers or [] -%}
{%- set c1 -%}{{ af.icon(pr.icon or '') }}{{ pr.title or '' }}{%- endset -%}
{{ af.button((l.socialUrl or '') ~ '/' ~ (pr.id or ''), '', af_skin('button', 'outline', 'w-full'), {'data-provider': pr.id or none}, c1) }}
{%- endfor -%}{%- endset -%}{{ af.stack('2', '', '', '', {'role': 'group', 'aria-label': l.providers or none, 'data-testid': 'authfly-providers'}, c2) }}
{%- endif -%}
{%- set c3 -%}{{ af.hidden('csrf', p.csrf or '') }}
{{ af.field({'label': l.identifier or '', 'for': id ~ '-identifier', 'formError': formError, 'input': {'type': 'email' if (p.identifier or 'any') == 'email' else 'text', 'name': 'identifier', 'required': true, 'attrs': {'autocomplete': 'email' if (p.identifier or 'any') == 'email' else 'username'}}}) }}
{%- if (p.method or 'password') == 'password' -%}
{{ af.field({'label': l.password or '', 'for': id ~ '-password', 'formError': formError, 'input': {'type': 'password', 'name': 'password', 'required': true, 'attrs': {'autocomplete': 'current-password'}}}) }}
{%- if l.forgot or '' -%}
{{ af.link(l.forgotHref or '', af_skin('link', 'w-fit text-sm'), 'forgot', l.forgot or '') }}
{%- endif -%}
{%- endif -%}
{{ af.button('', 'submit', af_skin('button', 'default', 'w-full'), {'data-testid': 'submit'}, af_esc(l.submit or '')) }}{%- endset -%}
{{ af.form(p.action or '', '', {'data-testid': 'authfly-form'}, c3) }}
{%- if l.magic or '' -%}
{{ af.button(l.magicHref or '', '', af_skin('button', 'outline', 'w-full'), {'data-testid': 'switch-method'}, af_esc(l.magic or '')) }}
{%- endif -%}
{%- if l.signupLink or '' -%}
{%- set c4 -%}{{ l.signupText or '' }} {{ af.link(l.signupHref or '', af_skin('link'), 'signup-link', l.signupLink or '') }}{%- endset -%}
{{ af.text('', af_text('muted'), {}, c4) }}
{%- endif -%}
{%- endset -%}
{{ af.card(af_skin('widgetCard'), {'data-testid': 'authfly-sign-in', 'aria-labelledby': none if p.landmarkLabel else id ~ '-title', 'aria-label': p.landmarkLabel or none}, c5) }}
